-- OpenCurtain Hospitals Import Script
-- Generated from Merged CMS + HIFLD Master Dataset (8,226 Unique Hospitals)
-- Supports direct execution in any SQL Client (pgAdmin, DBeaver, psql)

BEGIN;

-- 1. SAFE IN-PLACE UPSERT (Zero Data Loss: Preserves all existing hospital IDs, user reviews, bookmarks, and ratings)

ON CONFLICT ("cms_id") DO UPDATE SET
  "name" = EXCLUDED."name",
  "city" = EXCLUDED."city",
  "state" = EXCLUDED."state",
  "facility_type" = EXCLUDED."facility_type",
  "source" = EXCLUDED."source",
  "is_active" = EXCLUDED."is_active",
  "updated_at" = NOW();

-- 2. Populate hospital_units for all newly imported hospitals (links every hospital to active care units/departments)
SELECT h.id, u.id
FROM "hospitals" h
CROSS JOIN "units" u
WHERE u."deleted_at" IS NULL
ON CONFLICT ("hospital_id", "unit_id") DO NOTHING;

-- Reset sequences for hospitals and hospital_units
SELECT setval(pg_get_serial_sequence('"hospitals"', 'id'), COALESCE(MAX(id), 1)) FROM "hospitals";
SELECT setval(pg_get_serial_sequence('"hospital_units"', 'id'), COALESCE(MAX(id), 1)) FROM "hospital_units";

COMMIT;

SELECT COUNT(*) AS total_hospitals_imported FROM "hospitals";
SELECT COUNT(*) AS total_hospital_units_created FROM "hospital_units";